//go:embed migrations/*.sql
var migrationFS embed.FS

// Store provides PostgreSQL-backed persistence for the OpenSwarm control plane.
// All queries are generated by sqlc for type safety.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// New connects to PostgreSQL and returns a ready Store.
func New(ctx context.Context, databaseURL string) (*Store, error) {
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("store: connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("store: ping: %w", err)
	}
	return &Store{pool: pool, q: db.New(pool)}, nil
}

// Close releases the connection pool.
func (s *Store) Close() {
	s.pool.Close()
}

// Pool exposes the underlying pgxpool.Pool for direct use (e.g. transactions).
func (s *Store) Pool() *pgxpool.Pool {
	return s.pool
}

// ---------------------------------------------------------------------------
// Migrations
// ---------------------------------------------------------------------------

// RunMigrations reads embedded SQL files in lexicographic order and executes
// each one inside a transaction. Migrations containing the directive
// "-- no-transaction" on their first line are executed directly (required by
// PostgreSQL for commands like CREATE MATERIALIZED VIEW ... WITH DATA).
func (s *Store) RunMigrations(ctx context.Context) error {
	entries, err := fs.ReadDir(migrationFS, "migrations")
	if err != nil {
		return fmt.Errorf("store: read migrations dir: %w", err)
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Name() < entries[j].Name()
	})

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		data, err := migrationFS.ReadFile("migrations/" + entry.Name())
		if err != nil {
			return fmt.Errorf("store: read migration %s: %w", entry.Name(), err)
		}

		if bytes.Contains(data[:min(len(data), 100)], []byte("-- no-transaction")) {
			for _, stmt := range strings.Split(string(data), ";") {
				stmt = strings.TrimSpace(stmt)
				stripped := stripSQLComments(stmt)
				if stripped == "" {
					continue
				}
				if _, err := s.pool.Exec(ctx, stmt); err != nil {
					return fmt.Errorf("store: exec migration %s (no-tx): %w", entry.Name(), err)
				}
			}
			continue
		}

		tx, err := s.pool.Begin(ctx)
		if err != nil {
			return fmt.Errorf("store: begin tx for %s: %w", entry.Name(), err)
		}
		if _, err := tx.Exec(ctx, string(data)); err != nil {
			_ = tx.Rollback(ctx)
			return fmt.Errorf("store: exec migration %s: %w", entry.Name(), err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("store: commit migration %s: %w", entry.Name(), err)
		}
	}
	return nil
}

func stripSQLComments(s string) string {
	var lines []string
	for _, line := range strings.Split(s, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "--") {
			continue
		}
		lines = append(lines, trimmed)
	}
	return strings.Join(lines, "\n")
}

// ---------------------------------------------------------------------------
// Swarms (sqlc-backed)
// ---------------------------------------------------------------------------

func (s *Store) CreateSwarm(ctx context.Context, sw *domain.Swarm) error {
	specJSON, err := json.Marshal(sw.Spec)
	if err != nil {
		return fmt.Errorf("store: marshal swarm spec: %w", err)
	}
	row, err := s.q.CreateSwarm(ctx, db.CreateSwarmParams{
		Name:   sw.Name,
		Spec:   specJSON,
		Status: string(sw.Status),
	})
	if err != nil {
		return fmt.Errorf("store: create swarm: %w", err)
	}
	sw.ID = row.ID
	sw.CreatedAt = pgTime(row.CreatedAt)
	sw.UpdatedAt = pgTime(row.UpdatedAt)
	return nil
}

func (s *Store) ListSwarms(ctx context.Context) ([]domain.Swarm, error) {
	rows, err := s.q.ListSwarms(ctx)
	if err != nil {
		return nil, fmt.Errorf("store: list swarms: %w", err)
	}
	out := make([]domain.Swarm, 0, len(rows))
	for _, r := range rows {
		sw, err := swarmFromRow(r)
		if err != nil {
			return nil, err
		}
		out = append(out, sw)
	}
	return out, nil
}

func (s *Store) GetSwarmByName(ctx context.Context, name string) (*domain.Swarm, error) {
	r, err := s.q.GetSwarmByName(ctx, db.GetSwarmByNameParams{Name: name})
	if err != nil {
		return nil, fmt.Errorf("store: get swarm %q: %w", name, err)
	}
	sw, err := swarmFromRow(r)
	if err != nil {
		return nil, err
	}
	return &sw, nil
}

func (s *Store) DeleteSwarm(ctx context.Context, name string) error {
	// Cascade: delete tasks and agent_specs that reference this swarm first
	_, _ = s.pool.Exec(ctx, `DELETE FROM tasks WHERE swarm_id = (SELECT id FROM swarms WHERE name = $1)`, name)
	_, _ = s.pool.Exec(ctx, `DELETE FROM agent_specs WHERE swarm_id = (SELECT id FROM swarms WHERE name = $1)`, name)

	tag, err := s.q.DeleteSwarm(ctx, db.DeleteSwarmParams{Name: name})
	if err != nil {
		return fmt.Errorf("store: delete swarm %q: %w", name, err)
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("store: swarm %q not found", name)
	}
	return nil
}

func (s *Store) UpdateSwarmStatus(ctx context.Context, name string, status domain.SwarmStatus) error {
	tag, err := s.q.UpdateSwarmStatus(ctx, db.UpdateSwarmStatusParams{
		Status: string(status),
		Name:   name,
	})
	if err != nil {
		return fmt.Errorf("store: update swarm status %q: %w", name, err)
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("store: swarm %q not found", name)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Tasks (sqlc-backed)
// ---------------------------------------------------------------------------

func (s *Store) CreateTask(ctx context.Context, t *domain.Task) error {
	metaJSON, err := json.Marshal(t.Metadata)
	if err != nil {
		return fmt.Errorf("store: marshal task metadata: %w", err)
	}
	row, err := s.q.CreateTask(ctx, db.CreateTaskParams{
		SwarmName: t.SwarmName,
		AgentRole: t.AgentRole,
		Input:     t.Input,
		Status:    string(t.Status),
		Metadata:  metaJSON,
	})
	if err != nil {
		return fmt.Errorf("store: create task: %w", err)
	}
	t.ID = row.ID
	t.CreatedAt = pgTime(row.CreatedAt)
	return nil
}

func (s *Store) ListTasksBySwarm(ctx context.Context, swarmName string) ([]domain.Task, error) {
	rows, err := s.q.ListTasksBySwarm(ctx, db.ListTasksBySwarmParams{Name: swarmName})
	if err != nil {
		return nil, fmt.Errorf("store: list tasks for swarm %q: %w", swarmName, err)
	}
	out := make([]domain.Task, 0, len(rows))
	for _, r := range rows {
		out = append(out, taskFromListRow(r))
	}
	return out, nil
}

func (s *Store) GetTaskByID(ctx context.Context, id string) (*domain.Task, error) {
	r, err := s.q.GetTaskByID(ctx, db.GetTaskByIDParams{ID: id})
	if err != nil {
		return nil, fmt.Errorf("store: get task %q: %w", id, err)
	}
	t := taskFromGetRow(r)
	return &t, nil
}

func (s *Store) UpdateTaskStatus(ctx context.Context, id string, status domain.TaskStatus, assignedAgent string) error {
	if assignedAgent != "" {
		result, err := s.q.UpdateTaskStatus(ctx, db.UpdateTaskStatusParams{
			Status:          string(status),
			AssignedAgentID: pgtype.Text{String: assignedAgent, Valid: true},
			ID:              id,
		})
		if err != nil {
			return fmt.Errorf("store: update task status %q: %w", id, err)
		}
		if result.RowsAffected() == 0 {
			return fmt.Errorf("store: task %q not found", id)
		}
		return nil
	}
	result, err := s.q.UpdateTaskStatusOnly(ctx, db.UpdateTaskStatusOnlyParams{
		Status: string(status),
		ID:     id,
	})
	if err != nil {
		return fmt.Errorf("store: update task status %q: %w", id, err)
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("store: task %q not found", id)
	}
	return nil
}

func (s *Store) UpdateTaskResult(ctx context.Context, id string, output string, tokensUsed int, costUSD float64, latencyMs int64, taskErr string) error {
	now := time.Now()
	errText := pgtype.Text{}
	if taskErr != "" {
		errText = pgtype.Text{String: taskErr, Valid: true}
	}
	result, err := s.q.UpdateTaskResult(ctx, db.UpdateTaskResultParams{
		Output:      pgtype.Text{String: output, Valid: output != ""},
		TokensUsed:  int32(tokensUsed),
		CostUsd:     costUSD,
		LatencyMs:   pgtype.Int4{Int32: int32(latencyMs), Valid: true},
		Error:       errText,
		CompletedAt: pgtype.Timestamptz{Time: now, Valid: true},
		ID:          id,
	})
	if err != nil {
		return fmt.Errorf("store: update task result %q: %w", id, err)
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("store: task %q not found", id)
	}
	return nil
}

