// ---------------------------------------------------------------------------
// Type conversion helpers (sqlc pgtype ↔ domain types)
// ---------------------------------------------------------------------------

func pgTime(t pgtype.Timestamptz) time.Time {
	if t.Valid {
		return t.Time
	}
	return time.Time{}
}

func pgTimePtr(t pgtype.Timestamptz) *time.Time {
	if t.Valid {
		return &t.Time
	}
	return nil
}

func pgText(t pgtype.Text) string {
	if t.Valid {
		return t.String
	}
	return ""
}

func pgInt4ToInt64(i pgtype.Int4) int64 {
	if i.Valid {
		return int64(i.Int32)
	}
	return 0
}

func swarmFromRow(r db.Swarm) (domain.Swarm, error) {
	var sw domain.Swarm
	sw.ID = r.ID
	sw.Name = r.Name
	sw.Status = domain.SwarmStatus(r.Status)
	sw.CreatedAt = pgTime(r.CreatedAt)
	sw.UpdatedAt = pgTime(r.UpdatedAt)
	if err := json.Unmarshal(r.Spec, &sw.Spec); err != nil {
		return sw, fmt.Errorf("store: unmarshal swarm spec: %w", err)
	}
	return sw, nil
}

func policyFromRow(r db.Policy) (domain.Policy, error) {
	var p domain.Policy
	p.ID = r.ID
	p.Name = r.Name
	p.CreatedAt = pgTime(r.CreatedAt)
	if err := json.Unmarshal(r.Spec, &p.Spec); err != nil {
		return p, fmt.Errorf("store: unmarshal policy spec: %w", err)
	}
	return p, nil
}

func taskFromListRow(r db.ListTasksBySwarmRow) domain.Task {
	t := domain.Task{
		ID:            r.ID,
		SwarmName:     r.SwarmName,
		AgentRole:     r.AgentRole,
		AssignedAgent: pgText(r.AssignedAgentID),
		Input:         r.Input,
		Output:        pgText(r.Output),
		Status:        domain.TaskStatus(r.Status),
		TokensUsed:    int(r.TokensUsed),
		CostUSD:       r.CostUsd,
		LatencyMs:     pgInt4ToInt64(r.LatencyMs),
		Error:         pgText(r.Error),
		TraceID:       pgText(r.TraceID),
		CreatedAt:     pgTime(r.CreatedAt),
		CompletedAt:   pgTimePtr(r.CompletedAt),
	}
	if r.Metadata != nil {
		_ = json.Unmarshal(r.Metadata, &t.Metadata)
	}
	return t
}

func taskFromGetRow(r db.GetTaskByIDRow) domain.Task {
	t := domain.Task{
		ID:            r.ID,
		SwarmName:     r.SwarmName,
		AgentRole:     r.AgentRole,
		AssignedAgent: pgText(r.AssignedAgentID),
		Input:         r.Input,
		Output:        pgText(r.Output),
		Status:        domain.TaskStatus(r.Status),
		TokensUsed:    int(r.TokensUsed),
		CostUSD:       r.CostUsd,
		LatencyMs:     pgInt4ToInt64(r.LatencyMs),
		Error:         pgText(r.Error),
		TraceID:       pgText(r.TraceID),
		CreatedAt:     pgTime(r.CreatedAt),
		CompletedAt:   pgTimePtr(r.CompletedAt),
	}
	if r.Metadata != nil {
		_ = json.Unmarshal(r.Metadata, &t.Metadata)
	}
	return t
}

