// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

// GetSettings returns the platform settings for the given key ("global" for platform-wide).
func (s *Store) GetSettings(ctx context.Context, key string) (*domain.PlatformSettings, error) {
	row := s.pool.QueryRow(ctx,
		`SELECT config, updated_at FROM settings WHERE key = $1`, key)

	var configJSON []byte
	var updatedAt pgtype.Timestamptz
	if err := row.Scan(&configJSON, &updatedAt); err != nil {
		return nil, fmt.Errorf("get settings %s: %w", key, err)
	}

	var settings domain.PlatformSettings
	if len(configJSON) > 0 {
		if err := json.Unmarshal(configJSON, &settings); err != nil {
			return nil, fmt.Errorf("unmarshal settings: %w", err)
		}
	}
	settings.UpdatedAt = pgTime(updatedAt)
	return &settings, nil
}

// SaveSettings upserts the platform settings for the given key.
func (s *Store) SaveSettings(ctx context.Context, key string, settings *domain.PlatformSettings) error {
	configJSON, err := json.Marshal(settings)
	if err != nil {
		return fmt.Errorf("marshal settings: %w", err)
	}

	_, err = s.pool.Exec(ctx, `
		INSERT INTO settings (key, config, updated_at) VALUES ($1, $2, now())
		ON CONFLICT (key) DO UPDATE SET config = $2, updated_at = now()
	`, key, configJSON)
	if err != nil {
		return fmt.Errorf("save settings %s: %w", key, err)
	}
	return nil
}
